// Checks that openapi.json — the hand-maintained Swagger 2.0 spec for the
// legacy (unversioned) routes — still describes the Joi validation those
// routes actually run. It used to be generated by hapi-swagger; now a change
// to a route, or to the waste-movement-utils schemas the request bodies are
// built from, fails here until the spec is edited to match.
//
// Compared, from each Joi schema's describe(): which routes and methods
// exist, parameter and property names, types, unconditional `required`,
// enums and array length limits. Not compared: patterns, descriptions and
// examples, and conditional rules (`when`), which Swagger 2.0 can't express.
import { readFileSync } from 'node:fs'
import path from 'node:path'
import Hapi from '@hapi/hapi'
import { router } from '../plugins/router.js'

// The tags hapi-swagger's routeTag selected: reference-data routes were never
// documented
const DOCUMENTED_TAGS = ['movements', 'production-approval-tests']

const spec = JSON.parse(
  readFileSync(path.join(import.meta.dirname, 'openapi.json'), 'utf-8')
)

async function getLegacyRoutes() {
  const server = Hapi.server()
  await server.register(router)

  return server
    .table()
    .filter(
      ({ realm, settings }) =>
        realm.plugin === 'router' &&
        settings.tags?.some((tag) => DOCUMENTED_TAGS.includes(tag))
    )
    .map(({ method, path: routePath, settings }) => ({
      method,
      path: routePath,
      validate: settings.validate
    }))
}

const swaggerType = (joi) => {
  switch (joi.type) {
    case 'number':
      return joi.rules?.some(({ name }) => name === 'integer')
        ? 'integer'
        : 'number'
    case 'date':
      return 'string'
    case 'any':
      return undefined
    default:
      return joi.type
  }
}

const ruleLimit = (joi, ruleName) =>
  joi.rules?.find(({ name }) => name === ruleName)?.args.limit

const enumValues = (joi) =>
  joi.flags?.only
    ? (joi.allow ?? []).filter(
        (value) => value !== null && value !== '' && typeof value !== 'object'
      )
    : undefined

const isRequired = (joi) => joi.flags?.presence === 'required' && !joi.whens

// hapi-swagger left forbidden keys out of the spec, as they can't be sent
const withoutForbidden = (joiKeys) =>
  Object.fromEntries(
    Object.entries(joiKeys).filter(
      ([, joi]) => joi.flags?.presence !== 'forbidden'
    )
  )

const sorted = (values) => [...values].sort()

/**
 * The differences between Joi description `joi` and Swagger schema `swagger`,
 * as human-readable strings naming the field path they're at.
 */
function compareSchema(joi, swagger, at) {
  if (!swagger) {
    return [`${at}: missing from openapi.json`]
  }
  // hapi-swagger documented an alternatives schema as its first match
  if (joi.type === 'alternatives') {
    return compareSchema(joi.matches[0].schema, swagger, at)
  }

  const differences = []
  const compare = (what, expected, actual) => {
    if (JSON.stringify(expected) !== JSON.stringify(actual)) {
      differences.push(
        `${at}: ${what} is ${JSON.stringify(actual)} in openapi.json, but ${JSON.stringify(expected)} in Joi`
      )
    }
  }

  const type = swaggerType(joi)
  if (type) {
    compare('type', type, swagger.type)
  }

  const values = enumValues(joi)
  compare(
    'enum',
    values && sorted(values),
    swagger.enum && sorted(swagger.enum)
  )

  if (joi.type === 'array') {
    compare('minItems', ruleLimit(joi, 'min'), swagger.minItems)
    compare('maxItems', ruleLimit(joi, 'max'), swagger.maxItems)
    if (joi.items?.[0]) {
      differences.push(...compareSchema(joi.items[0], swagger.items, `${at}[]`))
    }
  }

  if (joi.type === 'object' && joi.keys) {
    differences.push(
      ...compareProperties(withoutForbidden(joi.keys), swagger, at)
    )
  }

  return differences
}

function compareProperties(joiKeys, swagger, at) {
  const properties = swagger.properties ?? {}
  const differences = Object.keys(properties)
    .filter((name) => !(name in joiKeys))
    .map((name) => `${at}.${name}: in openapi.json but not in Joi`)

  for (const [name, joi] of Object.entries(joiKeys)) {
    differences.push(...compareSchema(joi, properties[name], `${at}.${name}`))
  }

  // Conditionally required keys are left out of both sides
  const conditional = new Set(
    Object.keys(joiKeys).filter((name) => joiKeys[name].whens)
  )
  const expected = Object.keys(joiKeys).filter((name) =>
    isRequired(joiKeys[name])
  )
  const actual = (swagger.required ?? []).filter(
    (name) => !conditional.has(name)
  )
  if (JSON.stringify(sorted(expected)) !== JSON.stringify(sorted(actual))) {
    differences.push(
      `${at}: required is ${JSON.stringify(sorted(actual))} in openapi.json, but ${JSON.stringify(sorted(expected))} in Joi`
    )
  }

  return differences
}

/** Joi `params`/`query`/`headers` against the operation's parameters in `location`. */
function compareParameters(joiSchema, parameters, location, at) {
  const documented = parameters.filter(({ in: where }) => where === location)
  const joiKeys = joiSchema?.describe().keys ?? {}

  const differences = documented
    .filter(({ name }) => !(name in joiKeys))
    .map(
      ({ name }) =>
        `${at} ${location} '${name}': in openapi.json but not in Joi`
    )

  for (const [name, joi] of Object.entries(joiKeys)) {
    const parameter = documented.find((p) => p.name === name)
    if (!parameter) {
      differences.push(`${at} ${location} '${name}': missing from openapi.json`)
      continue
    }
    differences.push(
      ...compareSchema(joi, parameter, `${at} ${location} '${name}'`)
    )
    if (isRequired(joi) !== Boolean(parameter.required)) {
      differences.push(
        `${at} ${location} '${name}': required is ${Boolean(parameter.required)} in openapi.json, but ${isRequired(joi)} in Joi`
      )
    }
  }

  return differences
}

function compareOperation({ method, path: routePath, validate }) {
  const at = `${method} ${routePath}`
  const parameters = spec.paths[routePath]?.[method]?.parameters ?? []
  const body = parameters.find(({ in: where }) => where === 'body')

  return [
    ...compareParameters(validate.params, parameters, 'path', at),
    ...compareParameters(validate.query, parameters, 'query', at),
    ...compareParameters(validate.headers, parameters, 'header', at),
    ...(validate.payload
      ? compareSchema(validate.payload.describe(), body?.schema, `${at} body`)
      : [])
  ]
}

describe('openapi.json matches the Joi validation', () => {
  let legacyRoutes

  beforeAll(async () => {
    legacyRoutes = await getLegacyRoutes()
  })

  it('documents exactly the legacy routes', () => {
    const documented = Object.entries(spec.paths).flatMap(
      ([specPath, operations]) =>
        Object.keys(operations).map((method) => `${method} ${specPath}`)
    )
    const registered = legacyRoutes.map(
      ({ method, path: routePath }) => `${method} ${routePath}`
    )

    expect(sorted(documented)).toEqual(sorted(registered))
  })

  it("matches each legacy route's Joi validation", () => {
    expect(legacyRoutes.flatMap(compareOperation)).toEqual([])
  })
})
